sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var qp = request.queryParams;
        var challenge = qp.challenge || qp['hub.challenge'] || '';

        if (challenge) {
            response.setStatus(200);
            response.setHeader("Content-Type", "text/plain");
            response.setBody(String(challenge));   // return plain string
        } else {
            response.setStatus(200);
            response.setHeader("Content-Type", "application/json");
            response.setBody(JSON.stringify({ message: "Webhook is alive" }));  // must stringify
        }
    } catch (e) {
        response.setStatus(500);
        response.setHeader("Content-Type", "application/json");
        response.setBody(JSON.stringify({ error: e.message }));  // stringify here too
    }
})(request, response);
